module error_count(
	clk,
	rstn,
	signal_input,
	target,
	error_cur,
	error_last,
	sum_e);

	//---Ports declearation: generated by Robei---
	input clk;
	input rstn;
	input [31:0] signal_input;
	input [31:0] target;
	output [31:0] error_cur;
	output [31:0] error_last;
	output [31:0] sum_e;

	wire clk;
	wire rstn;
	wire [31:0] signal_input;
	wire [31:0] target;
	reg [31:0] error_cur;
	reg [31:0] error_last;
	reg [31:0] sum_e;

	//----Code starts here: integrated by Robei-----
	parameter [31:0] itg_max =  32'd100000000     ;       // 积分限幅，最大累加值为100
	parameter [31:0] itg_min   = -32'd100000000    ;       // 积分限幅，最小累加值为-100
	        
	                
	always @(posedge clk or negedge rstn) begin
	    if(!rstn) begin             // 复位
	        error_cur  <=  32'd0 ;
	        error_last  <=  32'd0 ;
	        sum_e      <=  32'd0 ;
	    end
	    else begin
	        error_cur   <=  target - signal_input   ;       // 误差信号e = 目标信号t - 反馈信号s
	        error_last   <=  error_cur             ;              // 将误差信号打一拍 得到上一时刻的误差值
	        // 由于二进制数使用补码表示正负，因此限幅的条件与简单的十进制数表示方法存在差异
	        if ((sum_e > itg_max) && (sum_e  <  32'h7FFF_FFFF)) begin
	            sum_e <= itg_max;
	        end
	        else if ((sum_e < itg_min) && (sum_e > 32'h8000_0000)) begin
	            sum_e <= itg_min;
	        end
	        else
	            sum_e  <= sum_e + error_cur     ;       // 积分误差累加                     
	    end
	end
	
	
	
endmodule    //error_count

